<!--
 * 消息批量发送列表页组件
 *
 * @path apps/message-web/src/views/batch/index.vue
 * @author ydsz-team
 * @since 1.0.0
 * @modified 4.1.0 由脚手架 CRUD 重写为消费契约 API（submitBatch 提交 + getProgress 进度查询）。
 * @modified 4.2.0 进度抽屉接入 SSE 实时推送（subscribeProgress），打开抽屉后持续订阅 progress/complete 事件；
 *           保留 getProgress 快照作为首屏加载与手动刷新。
-->
<script lang="ts" setup>
/**
 * 消息批量发送（列表页）
 * <p>消费后端契约 BatchController（src/api/batch.ts，auto-generated by bash/gen-contract.py）：
 * 本地维护已提交的批次列表（工具栏「新建批量」提交后把 batchId 存入列表），
 * 每行通过「进度」按钮打开抽屉，先取 getProgress({batchId}) 快照，再订阅
 * SSE（{@code /api/v1/message/batch/progress/{batchId}/sse}）实时刷新 progressPercent 等指标。
 * 契约无批次列表查询接口，故列表为本地快照，刷新页面后仅保留本次会话内提交的批次。
 *
 * @author ydsz-team
 * @since 1.0.0
 */
import type { VxeTableGridOptions } from '@ydsz/plugins/vxe-table';

import { Page, useYDSZModal } from '@ydsz/common-ui';

import {
  ElButton,
  ElDescriptions,
  ElDescriptionsItem,
  ElDrawer,
  ElProgress,
  ElTag,
} from 'element-plus';
import { h, onBeforeUnmount, ref, watch } from 'vue';
import { useI18n } from 'vue-i18n';

import { useYDSZVxeGrid } from '#/adapter/vxe-table';
import { getProgress } from '#/api/batch';
import type { BatchProgressVO, MsgBatchVO } from '#/api/models';
import { openSseStream } from '#/utils/sse-client';
import type { SseEventHandlers } from '#/utils/sse-client';

import BatchForm from './batch-form.vue';

defineOptions({ name: 'BatchManagement' });

const { t } = useI18n();

/** 状态列 Tag 类型映射（未知值按 info 展示） */
function getStatusType(status?: string): 'success' | 'danger' | 'warning' | 'info' {
  const upper = (status ?? '').toUpperCase();
  if (['SUCCESS', 'COMPLETED', 'DONE'].includes(upper)) return 'success';
  if (['FAILED', 'ERROR', 'PARTIAL'].includes(upper)) return 'danger';
  if (['RUNNING', 'PROCESSING', 'PENDING', 'QUEUED'].includes(upper)) return 'warning';
  return 'info';
}

/** 是否已进入终态（用于进度条判定） */
function statusDone(status?: string): boolean {
  return getStatusType(status) === 'success';
}

/** 本地已提交批次快照 */
const batchRows = ref<MsgBatchVO[]>([]);

const gridOptions: VxeTableGridOptions<MsgBatchVO> = {
  columns: [
    { type: 'seq', width: 50, title: t('common.seq') },
    { field: 'batchId', title: '批次ID', width: 220 },
    { field: 'batchName', title: '批次名称', width: 160 },
    { field: 'channel', title: '通道', width: 100 },
    { field: 'templateCode', title: t('templateCode'), width: 140 },
    { field: 'bizType', title: '业务类型', width: 110 },
    {
      field: 'status',
      title: t('common.status'),
      width: 100,
      slots: {
        default: ({ row }) =>
          h(ElTag, { type: getStatusType(row.status) }, () => row.status ?? '-'),
      },
    },
    {
      field: 'action',
      title: t('common.actions'),
      width: 100,
      fixed: 'right',
      slots: {
        default: ({ row }) =>
          h(
            ElButton,
            { size: 'small', link: true, type: 'primary', onClick: () => handleProgress(row) },
            () => '进度',
          ),
      },
    },
  ],
  height: 'auto',
  proxyConfig: {
    ajax: {
      query: async (_page, formValues) => {
        const keyword = String(formValues.batchName ?? '').trim();
        const items = keyword
          ? batchRows.value.filter((row) => (row.batchName ?? '').includes(keyword))
          : batchRows.value;
        return { items, total: items.length };
      },
    },
  },
  toolbarConfig: { custom: true, refresh: { code: 'query' }, search: true, zoom: true },
  formConfig: {
    enabled: true,
    items: [
      {
        field: 'batchName',
        title: '批次名称',
        itemRender: { name: 'Input', props: { placeholder: '批次名称' } },
      },
    ],
  },
};

const [Grid, gridApi] = useYDSZVxeGrid({ gridOptions });

const [BatchFormModal, batchFormApi] = useYDSZModal({ connectedComponent: BatchForm });

function handleAdd() {
  batchFormApi.open();
}

/** 提交成功后把批次写入本地列表（按 batchId 去重） */
function handleBatchCreated(batch: MsgBatchVO) {
  if (!batch.batchId) return;
  if (!batchRows.value.some((row) => row.batchId === batch.batchId)) {
    batchRows.value.unshift(batch);
  }
  gridApi.query();
}

/** 进度抽屉状态 */
const progressVisible = ref(false);
const progressLoading = ref(false);
const progressData = ref<BatchProgressVO | null>(null);
/** SSE 连接状态（idle/connecting/live/closed/error） */
const sseState = ref<'idle' | 'connecting' | 'live' | 'closed' | 'error'>('idle');
/** 当前订阅的批次 ID（用于抽屉关闭时清理与重复打开去重） */
let subscribedBatchId = '';
let closeSse = (() => undefined) as () => void;

/** SSE 连接状态文案映射 */
const sseStateText: Record<string, string> = {
  idle: '未连接',
  connecting: '连接中…',
  live: '实时推送中',
  closed: '已结束',
  error: '连接异常',
};

/** 关闭当前 SSE 流并复位连接状态（已结束/异常时保持终态文案） */
function stopSseStream(): void {
  closeSse();
  closeSse = () => undefined;
  if (subscribedBatchId) subscribedBatchId = '';
  if (sseState.value === 'connecting' || sseState.value === 'live') {
    sseState.value = 'closed';
  }
}

/** 合并 SSE 推送的进度增量（服务端按快照或字段级增量推送均可兼容） */
function applyProgressPatch(patch: Record<string, unknown>): void {
  if (!progressData.value) return;
  progressData.value = { ...progressData.value, ...(patch as Partial<BatchProgressVO>) };
}

/** 订阅批次 SSE 实时进度 */
function subscribeSseProgress(batchId: string): void {
  const controller = new AbortController();
  const handlers: SseEventHandlers & { signal?: AbortSignal } = {
    signal: controller.signal,
    onOpen: () => {
      sseState.value = 'live';
    },
    onEvent: (eventName, data) => {
      if (!data) return;
      if (eventName === 'progress') {
        applyProgressPatch(data);
      } else if (eventName === 'complete') {
        applyProgressPatch(data);
        sseState.value = 'closed';
        controller.abort();
      }
    },
    onError: () => {
      sseState.value = 'error';
    },
    onClose: () => {
      if (sseState.value === 'live' || sseState.value === 'connecting') {
        sseState.value = 'closed';
      }
    },
  };
  closeSse = openSseStream(`/api/v1/message/batch/progress/${batchId}/sse`, handlers);
}

/** 手动刷新进度快照（SSE 异常时兜底） */
async function refreshProgressSnapshot(): Promise<void> {
  if (!subscribedBatchId) return;
  try {
    const res = await getProgress({ batchId: subscribedBatchId });
    progressData.value = res;
  } catch {
    // 错误提示由请求拦截器统一处理
  }
}

async function handleProgress(row: MsgBatchVO) {
  if (!row.batchId) return;
  stopSseStream();
  progressLoading.value = true;
  try {
    const res = await getProgress({ batchId: row.batchId });
    progressData.value = res;
    subscribedBatchId = row.batchId;
    progressVisible.value = true;
    sseState.value = 'connecting';
    subscribeSseProgress(row.batchId);
  } catch {
    // 错误提示由请求拦截器统一处理
  } finally {
    progressLoading.value = false;
  }
}

/** 关闭抽屉时断开 SSE，避免后台残留长连接 */
watch(progressVisible, (visible) => {
  if (!visible) stopSseStream();
});

onBeforeUnmount(() => {
  stopSseStream();
});
</script>
<template>
  <Page auto-content-height>
    <Grid table-title="批量发送">
      <template #toolbar-tools>
        <ElButton type="primary" @click="handleAdd">{{ t('common.create') }}</ElButton>
      </template>
    </Grid>
    <BatchFormModal @success="handleBatchCreated" />
    <ElDrawer v-model="progressVisible" title="批次进度" :size="440" v-loading="progressLoading">
      <template #header>
        <div class="flex w-full items-center justify-between pr-2">
          <span>{{ t('page.batchSend') }}</span>
          <span class="flex items-center gap-2">
            <ElTag
              :type="sseState === 'live' ? 'success' : sseState === 'error' ? 'danger' : 'info'"
              size="small"
            >
              {{ sseStateText[sseState] }}
            </ElTag>
            <ElButton
              size="small"
              link
              type="primary"
              :disabled="!subscribedBatchId"
              @click="refreshProgressSnapshot"
            >
              {{ t('common.refresh') }}
            </ElButton>
          </span>
        </div>
      </template>
      <ElDescriptions v-if="progressData" :column="1" border size="small">
        <ElDescriptionsItem label="批次ID">{{ progressData.batchId ?? '-' }}</ElDescriptionsItem>
        <ElDescriptionsItem label="批次名称">{{
          progressData.batchName ?? '-'
        }}</ElDescriptionsItem>
        <ElDescriptionsItem label="通道">{{ progressData.channel ?? '-' }}</ElDescriptionsItem>
        <ElDescriptionsItem :label="t('templateCode')">{{
          progressData.templateCode ?? '-'
        }}</ElDescriptionsItem>
        <ElDescriptionsItem :label="t('common.status')">{{ progressData.status ?? '-' }}</ElDescriptionsItem>
        <ElDescriptionsItem label="进度">
          <ElProgress
            :percentage="Math.min(100, Number(progressData.progressPercent ?? 0))"
            :status="
              Number(progressData.progressPercent ?? 0) >= 100 || statusDone(progressData.status)
                ? 'success'
                : undefined
            "
            :stroke-width="12"
            class="w-56"
          />
        </ElDescriptionsItem>
        <ElDescriptionsItem label="总数">{{ progressData.total ?? 0 }}</ElDescriptionsItem>
        <ElDescriptionsItem label="已处理">{{ progressData.processed ?? 0 }}</ElDescriptionsItem>
        <ElDescriptionsItem label="成功">{{ progressData.success ?? 0 }}</ElDescriptionsItem>
        <ElDescriptionsItem label="失败">{{ progressData.failed ?? 0 }}</ElDescriptionsItem>
        <ElDescriptionsItem label="跳过">{{ progressData.skipped ?? 0 }}</ElDescriptionsItem>
        <ElDescriptionsItem label="错误信息">{{
          progressData.errorMessage ?? '-'
        }}</ElDescriptionsItem>
        <ElDescriptionsItem label="开始时间">{{
          progressData.startedAt ?? '-'
        }}</ElDescriptionsItem>
        <ElDescriptionsItem label="完成时间">{{
          progressData.completedAt ?? '-'
        }}</ElDescriptionsItem>
      </ElDescriptions>
    </ElDrawer>
  </Page>
</template>
